#include "ufbx.h"
#include <stdio.h>
int main(int argc,char**argv){ufbx_load_opts opts={0};opts.ignore_geometry=true;opts.load_external_files=false;ufbx_error error;for(int k=1;k<argc;k++){ufbx_scene*s=ufbx_load_file(argv[k],&opts,&error);if(!s){char b[2048];ufbx_format_error(b,sizeof(b),&error);fprintf(stderr,"FAILED %s: %s\n",argv[k],b);continue;}printf("FILE %s VERSION %u NODES %zu BONES %zu STACKS %zu WARNINGS %zu\n",argv[k],s->metadata.version,s->nodes.count,s->bones.count,s->anim_stacks.count,s->metadata.warnings.count);printf("CREATOR %.*s\n",(int)s->metadata.creator.length,s->metadata.creator.data);for(size_t i=0;i<s->anim_stacks.count;i++){ufbx_anim_stack*a=s->anim_stacks.data[i];printf("TAKE %.*s %.9g %.9g\n",(int)a->name.length,a->name.data,a->time_begin,a->time_end);}for(size_t i=0;i<s->nodes.count;i++){ufbx_node*n=s->nodes.data[i];printf("NODE %u PARENT %d NAME %.*s BONE %d\n",n->typed_id,n->parent?(int)n->parent->typed_id:-1,(int)n->name.length,n->name.data,n->bone!=0);}ufbx_free_scene(s);}return 0;}
